import re
from pathlib import Path

def parse_todos(text):
    fm = re.match(r'^---\n(.*?)\n---', text, re.S)
    if not fm:
        return []
    # only frontmatter lines under todos: until isProject or end
    lines = fm.group(1).splitlines()
    in_todos = False
    items = []
    cur = None
    for line in lines:
        if line.startswith('todos:'):
            in_todos = True
            continue
        if in_todos and re.match(r'^[a-zA-Z]', line):
            break
        if not in_todos:
            continue
        m = re.match(r'\s+- id:\s*(\S+)', line)
        if m:
            if cur: items.append(cur)
            cur = {'id': m.group(1), 'status': None, 'content': ''}
            continue
        if cur is None:
            continue
        sm = re.match(r'\s+status:\s*(\w+)', line)
        if sm:
            cur['status'] = sm.group(1)
            continue
        cm = re.match(r'\s+content:\s*(.*)', line)
        if cm:
            cur['content'] = cm.group(1).strip().strip('"\'')
    if cur: items.append(cur)
    return items

pending = []
for p in sorted(Path('.').glob('*.plan.md')):
    if p.parent != Path('.'):
        continue
    for t in parse_todos(p.read_text(encoding='utf-8', errors='replace')):
        if t['status'] == 'pending':
            pending.append((p.name, t['id'], t['content'][:100]))

print('catalog pending todos', len(pending))
