package analytics

import (
	"github.com/viletech/tools/vedy_bot/internal/analyze"
	"github.com/viletech/tools/vedy_bot/internal/conflict"
	"github.com/viletech/tools/vedy_bot/internal/estimate"
	"github.com/viletech/tools/vedy_bot/internal/normalize"
)

// ConflictItem is one plain-language contradiction on the analytics boundary.
type ConflictItem struct {
	Plain    string `json:"plain"`
	Question string `json:"question,omitempty"`
}

// EstimateView is the calendar heuristic exposed to cards/API/planfile.
type EstimateView struct {
	Todos         int     `json:"todos"`
	Hours         float64 `json:"hours"`
	ManagerPhrase string  `json:"manager_phrase"`
	EngineerNote  string  `json:"engineer_note,omitempty"`
}

// Bundle is the single in-process analytics contract (pipeline → card / plan / API).
// Not a separate service: package boundary only.
type Bundle struct {
	Class      string         `json:"class"`
	Confidence string         `json:"confidence"`
	Summary    string         `json:"summary"`
	Tags       []string       `json:"tags,omitempty"`
	Question   string         `json:"question,omitempty"`
	Chars      int            `json:"chars"`
	Words      int            `json:"words"`
	Conflicts  []ConflictItem `json:"conflicts,omitempty"`
	Estimate   EstimateView   `json:"estimate"`
}

// Result is the public DTO name for the analytics boundary (alias of Bundle).
type Result = Bundle

// InboxMeta is the flattened slice of Bundle written onto inbox records.
type InboxMeta struct {
	Class      string
	Confidence string
	Chars      int
	Tags       []string
}

// PlanMeta is the Bundle projection consumed by planfile drafts.
type PlanMeta struct {
	Class          string
	Conflicts      []string
	TimelinePhrase string
	EngineerNote   string
	Todos          int
	Hours          float64
}

// Run builds the analytics bundle from raw intake text (trigger still stripped inside Analyze).
func Run(raw, bot string) Bundle {
	a := analyze.Analyze(raw, bot)
	body := normalize.StripTrigger(raw, bot)
	findings := conflict.Detect(a.Class, a.Tags, body, nil)
	est := estimate.FromSignals(a.Class, a.Chars, a.Words, raw)
	out := Bundle{
		Class:      a.Class,
		Confidence: string(a.Confidence),
		Summary:    a.Summary,
		Tags:       a.Tags,
		Question:   a.Question,
		Chars:      a.Chars,
		Words:      a.Words,
		Estimate: EstimateView{
			Todos:         est.Todos,
			Hours:         est.Hours,
			ManagerPhrase: est.ManagerPhrase,
			EngineerNote:  est.EngineerNote,
		},
	}
	for _, f := range findings {
		out.Conflicts = append(out.Conflicts, ConflictItem{Plain: f.Plain, Question: f.Question})
	}
	return out
}

// AnalyzeResult projects Bundle back to analyze.Result for legacy call sites.
func (b Bundle) AnalyzeResult() analyze.Result {
	return analyze.Result{
		Class:      b.Class,
		Confidence: analyze.Confidence(b.Confidence),
		Chars:      b.Chars,
		Words:      b.Words,
		Tags:       b.Tags,
		Summary:    b.Summary,
		Question:   b.Question,
	}
}

// ConflictPlains returns only plain conflict strings for card storage.
func (b Bundle) ConflictPlains() []string {
	out := make([]string, 0, len(b.Conflicts))
	for _, c := range b.Conflicts {
		out = append(out, c.Plain)
	}
	return out
}

// ToInbox maps Bundle onto inbox jsonl fields (single contract → flat record).
func (b Bundle) ToInbox() InboxMeta {
	tags := append([]string(nil), b.Tags...)
	return InboxMeta{
		Class:      b.Class,
		Confidence: b.Confidence,
		Chars:      b.Chars,
		Tags:       tags,
	}
}

// ToPlan maps Bundle onto planfile Document scalars.
func (b Bundle) ToPlan() PlanMeta {
	return PlanMeta{
		Class:          b.Class,
		Conflicts:      b.ConflictPlains(),
		TimelinePhrase: b.Estimate.ManagerPhrase,
		EngineerNote:   b.Estimate.EngineerNote,
		Todos:          b.Estimate.Todos,
		Hours:          b.Estimate.Hours,
	}
}

// LowConfidence reports whether the bundle asks for clarify.
func (b Bundle) LowConfidence() bool {
	return b.Confidence == string(analyze.ConfidenceLow)
}

package analytics

import (
	"encoding/json"
	"testing"
)

func TestRunBundleTable(t *testing.T) {
	t.Parallel()
	cases := []struct {
		name         string
		raw          string
		wantClass    string
		wantConflict bool
	}{
		{name: "bug tag", raw: "@bot #баг падает кнопка оплаты на экране", wantClass: "bug"},
		{name: "short noise", raw: "@bot план", wantClass: "noise"},
		{name: "tag bug feature text", raw: "@bot #баг нужно добавить новую кнопку экспорта", wantClass: "bug", wantConflict: true},
	}
	for _, tc := range cases {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			got := Run(tc.raw, "bot")
			if got.Class != tc.wantClass {
				t.Fatalf("class=%q want %q", got.Class, tc.wantClass)
			}
			if got.Confidence != "low" && got.Confidence != "medium" && got.Confidence != "high" {
				t.Fatalf("confidence=%q", got.Confidence)
			}
			if tc.wantConflict && len(got.Conflicts) == 0 {
				t.Fatal("expected conflicts")
			}
			if got.Estimate.Todos < 1 {
				t.Fatalf("todos=%d", got.Estimate.Todos)
			}
			ar := got.AnalyzeResult()
			if ar.Class != got.Class {
				t.Fatal("AnalyzeResult mismatch")
			}
		})
	}
}

func TestBundleMappingTable(t *testing.T) {
	t.Parallel()
	cases := []struct {
		name        string
		raw         string
		wantClass   string
		wantLow     bool
		wantConflict bool
	}{
		{name: "clarify short", raw: "@bot ок", wantClass: "noise", wantLow: true},
		{name: "bug with conflict", raw: "@bot #баг нужно добавить новую кнопку экспорта", wantClass: "bug", wantConflict: true},
		{name: "feature change", raw: "@bot #доработка добавить фильтр в список заявок менеджера", wantClass: "change"},
	}
	for _, tc := range cases {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			b := Run(tc.raw, "bot")
			var asResult Result = b
			if asResult.Class != b.Class {
				t.Fatal("Result alias mismatch")
			}
			inbox := b.ToInbox()
			if inbox.Class != b.Class || inbox.Confidence != b.Confidence || inbox.Chars != b.Chars {
				t.Fatalf("ToInbox mismatch: %+v vs %+v", inbox, b)
			}
			if len(inbox.Tags) != len(b.Tags) {
				t.Fatalf("tags len %d want %d", len(inbox.Tags), len(b.Tags))
			}
			plan := b.ToPlan()
			if plan.Class != b.Class {
				t.Fatalf("ToPlan class=%q", plan.Class)
			}
			if plan.TimelinePhrase != b.Estimate.ManagerPhrase {
				t.Fatalf("timeline=%q", plan.TimelinePhrase)
			}
			if plan.Todos != b.Estimate.Todos || plan.Hours != b.Estimate.Hours {
				t.Fatalf("estimate map todos=%d hours=%v", plan.Todos, plan.Hours)
			}
			if len(plan.Conflicts) != len(b.ConflictPlains()) {
				t.Fatalf("conflicts map %d vs %d", len(plan.Conflicts), len(b.ConflictPlains()))
			}
			if tc.wantClass != "" && b.Class != tc.wantClass {
				t.Fatalf("class=%q want %q", b.Class, tc.wantClass)
			}
			if tc.wantLow && !b.LowConfidence() {
				t.Fatal("want low confidence")
			}
			if tc.wantConflict && len(plan.Conflicts) == 0 {
				t.Fatal("want plan conflicts")
			}
			raw, err := json.Marshal(b)
			if err != nil {
				t.Fatal(err)
			}
			var round Bundle
			if err := json.Unmarshal(raw, &round); err != nil {
				t.Fatal(err)
			}
			if round.Class != b.Class || round.Estimate.Todos != b.Estimate.Todos {
				t.Fatalf("json roundtrip %#v", round)
			}
		})
	}
}

