if p.WithAnalyze || p.WithHITL {
	meta := bundle.ToInbox()
	rec.Class = meta.Class
	rec.Confidence = meta.Confidence
	rec.Chars = meta.Chars
	rec.Tags = meta.Tags
	if bundle.LowConfidence() {
		rec.Kind = "clarify"
