package router

// Channel is the Telegram surface for a mirrored thread line.
type Channel string

const (
	ChannelManager  Channel = "manager"
	ChannelOperator Channel = "operator"
	ChannelUnknown  Channel = "unknown"
)

// Classify maps chat id to manager vs operator allowlists.
func Classify(chatID int64, manager, operator map[int64]struct{}) Channel {
	if _, ok := manager[chatID]; ok {
		return ChannelManager
	}
	if _, ok := operator[chatID]; ok {
		return ChannelOperator
	}
	return ChannelUnknown
}

// Allowed reports whether the chat is in either allowlist.
func Allowed(chatID int64, manager, operator map[int64]struct{}) bool {
	return Classify(chatID, manager, operator) != ChannelUnknown
}

// Primary returns the first id from the set (stable enough for single-chat configs).
func Primary(ids map[int64]struct{}) int64 {
	for id := range ids {
		return id
	}
	return 0
}

// IsOperatorBound reports whether outbound kind is routed to the operator chat when configured.
// AP2b: reminders, agent digests, operator prompts → operator; proposal/help/stale/ack → manager.
func IsOperatorBound(kind string) bool {
	switch kind {
	case "reminder", "operator_digest", "operator_prompt":
		return true
	default:
		return false
	}
}

// TargetForKind picks destination chat for outbound bot traffic.
// Operator-bound kinds use TELEGRAM_OPERATOR_CHAT_IDS when set; otherwise fall back to manager/fallback.
// Manager-bound (proposal, help, stale, stand, …): ack stays on the manager intake chat.
func TargetForKind(kind string, manager, operator map[int64]struct{}, fallback int64) (chatID int64, channel Channel) {
	if IsOperatorBound(kind) {
		if id := Primary(operator); id != 0 {
			return id, ChannelOperator
		}
		if fallback != 0 {
			return fallback, Classify(fallback, manager, operator)
		}
		return Primary(manager), ChannelManager
	}
	if fallback != 0 {
		ch := Classify(fallback, manager, operator)
		if ch == ChannelUnknown {
			ch = ChannelManager
		}
		return fallback, ch
	}
	return Primary(manager), ChannelManager
}

package router

import "testing"

func TestClassifyAndAllowed(t *testing.T) {
	t.Parallel()
	manager := map[int64]struct{}{-100: {}}
	operator := map[int64]struct{}{-200: {}}
	if Classify(-100, manager, operator) != ChannelManager {
		t.Fatal("manager")
	}
	if Classify(-200, manager, operator) != ChannelOperator {
		t.Fatal("operator")
	}
	if Allowed(-1, manager, operator) {
		t.Fatal("unknown not allowed")
	}
	if !Allowed(-100, manager, operator) || !Allowed(-200, manager, operator) {
		t.Fatal("allowlists")
	}
}

func TestTargetForKindMatrix(t *testing.T) {
	t.Parallel()
	manager := map[int64]struct{}{-100: {}}
	operator := map[int64]struct{}{-200: {}}
	cases := []struct {
		kind    string
		opSet   map[int64]struct{}
		wantID  int64
		wantCh  Channel
		opBound bool
	}{
		{kind: "reminder", opSet: operator, wantID: -200, wantCh: ChannelOperator, opBound: true},
		{kind: "operator_digest", opSet: operator, wantID: -200, wantCh: ChannelOperator, opBound: true},
		{kind: "operator_prompt", opSet: operator, wantID: -200, wantCh: ChannelOperator, opBound: true},
		{kind: "proposal", opSet: operator, wantID: -100, wantCh: ChannelManager, opBound: false},
		{kind: "help", opSet: operator, wantID: -100, wantCh: ChannelManager, opBound: false},
		{kind: "stale", opSet: operator, wantID: -100, wantCh: ChannelManager, opBound: false},
		{kind: "stand", opSet: operator, wantID: -100, wantCh: ChannelManager, opBound: false},
		// No operator chat → reminder falls back to manager intake.
		{kind: "reminder", opSet: nil, wantID: -100, wantCh: ChannelManager, opBound: true},
		{kind: "operator_digest", opSet: nil, wantID: -100, wantCh: ChannelManager, opBound: true},
	}
	for _, tc := range cases {
		tc := tc
		t.Run(tc.kind+"_"+string(tc.wantCh), func(t *testing.T) {
			t.Parallel()
			if IsOperatorBound(tc.kind) != tc.opBound {
				t.Fatalf("IsOperatorBound(%q)=%v", tc.kind, IsOperatorBound(tc.kind))
			}
			id, ch := TargetForKind(tc.kind, manager, tc.opSet, -100)
			if id != tc.wantID || ch != tc.wantCh {
				t.Fatalf("got %d %s want %d %s", id, ch, tc.wantID, tc.wantCh)
			}
		})
	}
}

func TestPrimary(t *testing.T) {
	t.Parallel()
	if Primary(nil) != 0 {
		t.Fatal("empty")
	}
	id := Primary(map[int64]struct{}{-200: {}})
	if id != -200 {
		t.Fatalf("id=%d", id)
	}
}

