/** Compose text for selective TG publish preview (AP4). */
export function composePublishText(input: {
  selection?: string;
  planSummary?: string;
  includePlan?: boolean;
}): string {
  const selection = String(input.selection || "").trim();
  const plan = input.includePlan ? String(input.planSummary || "").trim() : "";
  if (selection && plan) {
    return `${selection}\n\n${plan}`;
  }
  return selection || plan;
}

/** Format plan name+overview for optional publish append. */
export function formatPlanPublishSummary(input: {
  name?: string;
  overview?: string;
}): string {
  const name = String(input.name || "").trim();
  const overview = String(input.overview || "").trim();
  if (!name && !overview) {
    return "";
  }
  if (!overview) {
    return `План: ${name}`;
  }
  if (!name) {
    return `Кратко по плану:\n${overview}`;
  }
  return `План «${name}»:\n${overview}`;
}

import { useState } from "react";
import { SendHorizontal, Sparkle, Trash2, X } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { composePublishText } from "@/lib/api/publish-compose";

type Props = {
  count: number;
  busy?: boolean;
  previewText?: string;
  planSummary?: string;
  onClear: () => void;
  onAnalyzeSelected: (prompt: string) => void;
  onAnalyzeChat: () => void;
  onAskAgent: (prompt: string) => void;
  onPublish?: (text: string, target: "manager" | "operator") => void;
  onMgmtDone?: (title: string, body: string) => void;
  onDeleteSelected?: () => void;
};

export function SelectionBar({
  count,
  busy,
  previewText = "",
  planSummary = "",
  onClear,
  onAnalyzeSelected,
  onAnalyzeChat,
  onAskAgent,
  onPublish,
  onMgmtDone,
  onDeleteSelected,
}: Props) {
  const [question, setQuestion] = useState("");
  const [publishPreview, setPublishPreview] = useState(false);
  const [edited, setEdited] = useState("");
  const [target, setTarget] = useState<"manager" | "operator">("manager");
  const [includePlan, setIncludePlan] = useState(false);
  if (count === 0) return null;

  function openPublishPreview() {
    setIncludePlan(false);
    setEdited(
      composePublishText({
        selection: previewText || question,
        planSummary,
        includePlan: false,
      }),
    );
    setPublishPreview(true);
  }

  function toggleIncludePlan(next: boolean) {
    setIncludePlan(next);
    setEdited(
      composePublishText({
        selection: previewText || question,
        planSummary,
        includePlan: next,
      }),
    );
  }

  return (
    <div className="mx-auto w-full max-w-4xl px-4 pb-2">
      <div className="rounded-xl border border-primary/50 bg-surface-raised p-3 shadow-lg">
        <div className="flex items-center justify-between gap-3">
          <p className="font-mono text-xs text-foreground">
            Выбрано: <span className="text-primary">{count}</span>
          </p>
          <Button
            variant="ghost"
            size="sm"
            className="h-7 gap-1 font-mono text-[11px] text-muted-foreground"
            onClick={onClear}
            disabled={busy}
          >
            <X className="size-3" /> Снять выбор
          </Button>
        </div>

        <Textarea
          value={question}
          onChange={(e) => setQuestion(e.target.value)}
          placeholder="Вопрос агенту по выбранным сообщениям…"
          className="mt-2 min-h-16 resize-none border-border bg-background/50 text-sm"
          disabled={busy}
        />

        <div className="mt-2 flex flex-wrap gap-2">
          <Button
            size="sm"
            className="gap-1.5"
            disabled={busy}
            onClick={() => onAnalyzeSelected(question.trim())}
          >
            <Sparkle className="size-3.5" /> Разобрать выбранные
          </Button>
          <Button
            size="sm"
            variant="outline"
            className="border-border bg-surface"
            disabled={busy}
            onClick={onAnalyzeChat}
          >
            Разобрать весь чат
          </Button>
          <Button
            size="sm"
            variant="outline"
            className="border-border bg-surface"
            disabled={busy}
            onClick={() => onAskAgent(question.trim())}
          >
            Спросить у агента
          </Button>
          {onPublish && (
            <Button
