python3 <<'PY'
import re, pathlib, yaml
from collections import Counter, defaultdict

root = pathlib.Path("/Users/levpogosov/Downloads/viletech-platform/.cursor/plans")

# collect 73 from batches
items = []
for i in range(1, 8):
    text = (root / f"open_plans_batch_0{i}.plan.md").read_text(encoding="utf-8")
    for m in re.finditer(r'content: "Triage ([^"]+)\.plan\.md:', text):
        items.append((i, m.group(1)))

print(f"batch items: {len(items)}")

def parse_frontmatter(path):
    raw = path.read_text(encoding="utf-8", errors="replace")
    if not raw.startswith("---"):
        return None, raw
    parts = raw.split("---", 2)
    if len(parts) < 3:
        return None, raw
    try:
        fm = yaml.safe_load(parts[1]) or {}
    except Exception as e:
        return {"_yaml_error": str(e)}, parts[2]
    return fm, parts[2]

def todo_stats(fm):
    todos = fm.get("todos") or []
    c = Counter()
    for t in todos:
        if isinstance(t, dict):
            c[str(t.get("status") or "missing")] += 1
        else:
            c["invalid"] += 1
    return c, len(todos)

def body_dod(body):
    open_c = len(re.findall(r"^- \[ \]", body, re.M))
    done_c = len(re.findall(r"^- \[x\]", body, re.M | re.I))
    return open_c, done_c

def classify(slug, fm, body, exists):
    if not exists:
        return "MISSING_FILE"
    overview = str((fm or {}).get("overview") or "")
    low = (overview + "\n" + (body or "")[:2000]).lower()
    if "superseded" in low or "не исполнять" in low or "do not execute" in low:
        return "SUPERSEDED"
    c, n = todo_stats(fm or {})
    open_n = c.get("pending", 0) + c.get("in_progress", 0)
    done_n = c.get("completed", 0)
    canc_n = c.get("cancelled", 0)
    dod_open, dod_done = body_dod(body or "")
    if n == 0:
        # no todos — look at overview/status keywords
        if "completed" in low and open_n == 0:
            return "LIKELY_DONE_NO_TODOS"
        return "NO_TODOS_UNCLEAR"
    if open_n == 0 and done_n + canc_n == n:
        if dod_open > 0:
            return "TODOS_CLOSED_DOD_OPEN"  # honesty gap
        return "CLOSED"
    if open_n > 0 and done_n == 0 and canc_n == 0:
        return "ALL_OPEN"
    if open_n > 0:
        return "PARTIAL"
    return "OTHER"

rows = []
for batch, slug in items:
    # find file
    candidates = list(root.glob(f"{slug}.plan.md"))
    if not candidates:
        # fuzzy for cyrillic already in slug
        candidates = [p for p in root.glob("*.plan.md") if p.stem == slug or slug in p.stem]
    path = candidates[0] if candidates else None
    exists = path is not None and path.exists()
    fm, body = (None, "")
    if exists:
        fm, body = parse_frontmatter(path)
    cat = classify(slug, fm, body, exists)
    c, n = todo_stats(fm or {}) if exists else (Counter(), 0)
    open_n = c.get("pending", 0) + c.get("in_progress", 0)
    done_n = c.get("completed", 0)
    canc_n = c.get("cancelled", 0)
    dod_open, dod_done = body_dod(body) if exists else (0, 0)
    overview = str((fm or {}).get("overview") or "")[:120]
    rows.append({
        "batch": batch, "slug": slug, "cat": cat, "exists": exists,
        "open": open_n, "done": done_n, "canc": canc_n, "n": n,
        "dod_open": dod_open, "overview": overview.replace("\n"," "),
        "path": path.name if path else None,
    })

by = Counter(r["cat"] for r in rows)
print("\nCATEGORIES:")
for k,v in by.most_common():
    print(f"  {k}: {v}")

print("\n--- by category detail ---")
for cat in ["MISSING_FILE","SUPERSEDED","CLOSED","TODOS_CLOSED_DOD_OPEN","PARTIAL","ALL_OPEN","NO_TODOS_UNCLEAR","LIKELY_DONE_NO_TODOS","OTHER"]:
    subset = [r for r in rows if r["cat"]==cat]
    if not subset: continue
